-- __NAME__: position marker for guardrail-observer (generated by scripts/gen-probes.sh; do not edit by hand).
--
-- A probe does no inspection and makes no decision. It records "the request reached priority
-- __PRIORITY__" in the request context so the head plugin can work out, in its log phase:
--   * which plugin stopped a request  (the gap after the last probe that ran)
--   * how long each gap took          (timestamp difference between neighbouring probes)
--   * where the body was rewritten    (hash difference between neighbouring probes)
-- Open-source Kong gives a plugin one fixed priority, so each position is its own tiny plugin.

local sha256 = require "resty.sha256"
local to_hex = require("resty.string").to_hex

local PRIORITY = __PRIORITY__
local Probe = { PRIORITY = PRIORITY, VERSION = "0.2.0" }
local CODE = ngx.md5("gro:" .. PRIORITY):sub(1, 4)

local function now_ms()
  ngx.update_time()
  return math.floor(ngx.now() * 1000)
end

function Probe:access(conf)
  local ctx = ngx.ctx
  local trail = ctx.gro_trail
  if not trail then return end            -- head plugin not on this request: stay silent
  local e = { p = PRIORITY, t = now_ms() }
  if conf.hash_body then
    local body = ngx.req.get_body_data()  -- already read by the head plugin; nil when spilled to a file
    if body then
      e.n = #body
      if #body <= conf.max_hash_bytes then
        local d = sha256:new(); d:update(body)
        e.h = to_hex(d:final()):sub(1, 16)
      end
    end
  end
  trail[#trail + 1] = e
  if conf.emit_header then
    local codes = {}
    for i, x in ipairs(trail) do codes[i] = ngx.md5("gro:" .. x.p):sub(1, 4) end
    kong.service.request.set_header(conf.header_name, table.concat(codes, "."))
  end
end

function Probe:header_filter(conf)
  local ctx = ngx.ctx
  if not ctx.gro_trail then return end
  local rt = ctx.gro_rtrail
  if not rt then rt = {}; ctx.gro_rtrail = rt end
  rt[#rt + 1] = { p = PRIORITY, chunks = 0, bytes = 0, _h = conf.hash_body and sha256:new() or nil }
  ctx["gro_rprobe_" .. PRIORITY] = rt[#rt]
end

function Probe:body_filter(conf)
  local s = ngx.ctx["gro_rprobe_" .. PRIORITY]
  if not s then return end
  local chunk, eof = ngx.arg[1], ngx.arg[2]
  if chunk and #chunk > 0 then
    s.chunks = s.chunks + 1
    s.bytes = s.bytes + #chunk
    if s.chunks == 1 then s.first_ms = now_ms() end
    if s._h then s._h:update(chunk) end
  end
  if eof then
    s.eof_ms = now_ms()
    if s._h and s.chunks > 0 then s.sha256 = to_hex(s._h:final()) end
    s._h = nil
  end
end

Probe.CODE = CODE
return Probe
